import { test, expect } from '@playwright/test';

test.describe('File Upload Progress Bar', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display progress bar when uploading a single file', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    await fileInput.setInputFiles('test-file.txt');

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();
  });

  test('should show progress bar for each file in multi-file upload', async ({ page }) => {
    const fileInput = page.getByLabel(/choose files|select files|upload files/i);

    await fileInput.setInputFiles(['test-file-1.txt', 'test-file-2.txt']);

    const progressBars = page.getByRole('progressbar');
    const count = await progressBars.count();
    expect(count).toBeGreaterThanOrEqual(1);
  });

  test('should update progress bar value during file upload', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    await fileInput.setInputFiles('test-file.txt');

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    const ariaValueNow = await progressBar.getAttribute('aria-valuenow');
    expect(ariaValueNow).toBeDefined();
    const progressValue = parseInt(ariaValueNow || '0', 10);
    expect(progressValue).toBeGreaterThanOrEqual(0);
    expect(progressValue).toBeLessThanOrEqual(100);
  });

  test('should display file name with progress bar', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    await fileInput.setInputFiles('test-file.txt');

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    const fileNameText = page.getByText(/test-file/i);
    await expect(fileNameText).toBeVisible();
  });

  test('should hide progress bar after file upload completes', async ({ page }) => {
    const fileInput = page.getByLabel(/choose file|select file|upload file/i);

    await fileInput.setInputFiles('test-file.txt');

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    await page.waitForTimeout(2000);

    const uploadComplete = page.getByText(/upload complete|success|done/i);
    await expect(uploadComplete).toBeVisible({ timeout: 5000 });
  });
});
